153	    /**
154	     * The known E.164 country calling codes this owner's telephone may carry, used only to split the
155	     * stored number into its country code and national digits for display. Australia ('+61') and the
156	     * North American Numbering Plan ('+1') mirror the codes the create endpoint recognises.
157	     */
158	    private static final String[] KNOWN_COUNTRY_CODES = {"61", "1"};
159	
160	    /**
161	     * The stored E.164 {@code telephone} formatted for human reading: the country calling code (kept
162	     * with its leading {@code '+'}), a space, then the national digits grouped in threes from the left
163	     * and separated by spaces (e.g. {@code +61412345678} becomes {@code "+61 412 345 678"}). The
164	     * country code is taken as the longest {@link #KNOWN_COUNTRY_CODES} match, defaulting to a
165	     * two-digit code when none is recognised. It is a derived value; the raw {@code telephone} stays in
166	     * E.164 form.
167	     *
168	     * @return the human-formatted telephone, or the raw {@code telephone} when it is {@code null} or
169	     *         not in E.164 form
170	     */
171	    public String getTelephoneDisplay() {
172	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
173	            return this.telephone;
174	        }
175	        String digits = this.telephone.substring(1);
176	        String countryCode = null;
177	        for (String code : KNOWN_COUNTRY_CODES) {
178	            if (digits.startsWith(code) && digits.length() > code.length()
179	                && (countryCode == null || code.length() > countryCode.length())) {
180	                countryCode = code;
181	            }
182	        }
183	        if (countryCode == null) {
184	            countryCode = digits.substring(0, Math.min(2, digits.length()));
185	        }
186	        String national = digits.substring(countryCode.length());
187	        StringBuilder sb = new StringBuilder("+").append(countryCode);
188	        for (int i = 0; i < national.length(); i += 3) {
189	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
190	        }
191	        return sb.toString();
192	    }
