344	    /**
345	     * The fiscal year in which a date falls, where the fiscal year starts on 1 July. A date on or after
346	     * 1 July belongs to the fiscal year ending in the following calendar year; a date before 1 July
347	     * belongs to the fiscal year ending in that same calendar year. The returned value is the fiscal
348	     * year's ending calendar year (e.g. {@code 2026-08-10} yields {@code 2027}, {@code 2026-05-10}
349	     * yields {@code 2026}).
350	     *
351	     * @param date the date to classify
352	     * @return the ending calendar year of the fiscal year the date falls in
353	     */
354	    public static int fiscalYear(LocalDate date) {
355	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
356	    }
