358	    /**
359	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal
360	     * year (which starts on 1 July) that the business-day-adjusted {@code registrationDate} falls in
361	     * (e.g. a registration date of {@code 2026-08-10} yields {@code 'FY27'}). It is a derived,
362	     * non-persistent value; when no {@code registrationDate} is present it is {@code null}.
363	     *
364	     * @return the {@code 'FY<YY>'} fiscal year, or {@code null} when no registration date is present
365	     */
366	    public String getFiscalYear() {
367	        if (this.registrationDate == null) {
368	            return null;
369	        }
370	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
371	    }
