373	    /**
374	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
375	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
376	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
377	     * 3), and 3 points for tenure &mdash; the number of elapsed fiscal years (the fiscal year starts on
378	     * 1 July) from {@code registrationDate} to today &mdash; of more than 1.
379	     *
380	     * @return the derived membership points (0 or more)
381	     */
382	    public Integer getMembershipPoints() {
383	        int points = 0;
384	        if (this.email != null && !this.email.isBlank()) {
385	            points += 2;
386	        }
387	        if (this.namesakeCount != null && this.namesakeCount == 0) {
388	            points += 1;
389	        }
390	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
391	            points += 2;
392	        }
393	        if (this.registrationDate != null
394	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) > 1) {
395	            points += 3;
396	        }
397	        return points;
398	    }
