400	    /**
401	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
402	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
403	     * points. The result is then capped at the owner's {@link #getMembershipLevelCeiling() membership
404	     * level ceiling} when one is set, so a new owner never exceeds one above the highest level among the
405	     * other members of its household at the time it was created.
406	     *
407	     * @return the derived membership level (1 to 4), capped at the membership-level ceiling when set
408	     */
409	    public Integer getMembershipLevel() {
410	        int points = getMembershipPoints();
411	        int level;
412	        if (points >= 6) {
413	            level = 4;
414	        } else if (points >= 4) {
415	            level = 3;
416	        } else if (points >= 2) {
417	            level = 2;
418	        } else {
419	            level = 1;
420	        }
421	        if (this.membershipLevelCeiling != null && level > this.membershipLevelCeiling) {
422	            return this.membershipLevelCeiling;
423	        }
424	        return level;
425	    }
