427	    /**
428	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
429	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
430	     *
431	     * @return the single Luhn check digit, or {@code null} when there is no customer code
432	     */
433	    public Integer getCheckDigit() {
434	        if (this.customerCode == null) {
435	            return null;
436	        }
437	        int sum = 0;
438	        boolean dbl = true;
439	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
440	            char c = this.customerCode.charAt(i);
441	            if (c < '0' || c > '9') {
442	                continue;
443	            }
444	            int d = c - '0';
445	            if (dbl) {
446	                d *= 2;
447	                if (d > 9) {
448	                    d -= 9;
449	                }
450	            }
451	            sum += d;
452	            dbl = !dbl;
453	        }
454	        return (10 - (sum % 10)) % 10;
455	    }
