457	    /**
458	     * The owner's age band, derived from {@code birthDate} computed against {@code registrationDate}:
459	     * {@code MINOR} when the owner is under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65
460	     * or older. It is a derived, non-persistent value; when no {@code birthDate} is present it is
461	     * {@code null}.
462	     *
463	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
464	     *         is present
465	     */
466	    public String getAgeBand() {
467	        if (this.birthDate == null) {
468	            return null;
469	        }
470	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
471	        int age = java.time.Period.between(this.birthDate, reference).getYears();
472	        if (age < 18) {
473	            return "MINOR";
474	        }
475	        if (age < 65) {
476	            return "ADULT";
477	        }
478	        return "SENIOR";
479	    }
