491	    /**
492	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
493	     * lower-case SHA-256 hex digest over the owner's normalized telephone (empty when none), its
494	     * lower-cased email (empty when none) and the Soundex code of its last name, joined by {@code '|'}.
495	     * Because the telephone is part of the key, two members of the same household with different
496	     * telephones have different identity keys; only owners whose whole key is identical are duplicates.
497	     *
498	     * @return the SHA-256 hex identity key over {@code normalizedTelephone|lowerEmail|soundex(lastName)}
499	     */
500	    public String getIdentityKey() {
501	        String telephonePart = this.telephone == null ? "" : this.telephone;
502	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
503	        String key = telephonePart + '|' + emailPart + '|' + soundex(getLastName());
504	        return sha256Hex(key);
505	    }
506	
507	    /** Lower-case index (a=0 .. z=25) to Soundex digit, using the standard Soundex code table. */
508	    private static final char[] SOUNDEX_MAP = "01230120022455012623010202".toCharArray();
509	
510	    /**
511	     * The standard (American) Soundex code of a name: its first letter followed by three digits, so
512	     * names that sound alike share a code (e.g. {@code "Robert"} and {@code "Rupert"} both yield
513	     * {@code "R163"}). Non-letters are ignored and case is irrelevant; a value with no letters yields
514	     * an empty string.
515	     *
516	     * @param value the name to encode, or {@code null}
517	     * @return the four-character Soundex code, or an empty string when the value holds no letters
518	     */
519	    public static String soundex(String value) {
520	        if (value == null) {
521	            return "";
522	        }
523	        StringBuilder letters = new StringBuilder();
524	        for (int i = 0; i < value.length(); i++) {
525	            char c = value.charAt(i);
526	            if (c >= 'A' && c <= 'Z') {
527	                letters.append(c);
528	            } else if (c >= 'a' && c <= 'z') {
529	                letters.append((char) (c - ('a' - 'A')));
530	            }
531	        }
532	        if (letters.length() == 0) {
533	            return "";
534	        }
535	        String s = letters.toString();
536	        char[] out = {'0', '0', '0', '0'};
537	        out[0] = s.charAt(0);
538	        char last = soundexCode(s, 0);
539	        int count = 1;
540	        for (int i = 1; i < s.length() && count < out.length; i++) {
541	            char mapped = soundexCode(s, i);
542	            if (mapped != 0) {
543	                if (mapped != '0' && mapped != last) {
544	                    out[count++] = mapped;
545	                }
546	                last = mapped;
547	            }
548	        }
549	        return new String(out);
550	    }
551	
552	    /**
553	     * The Soundex digit contributed by the letter at {@code index}, honouring the rule that two
554	     * like-coded consonants separated only by {@code 'H'} or {@code 'W'} count once: such a letter
555	     * returns the null character {@code 0} so the caller skips it without resetting the running code.
556	     */
557	    private static char soundexCode(String s, int index) {
558	        char mapped = SOUNDEX_MAP[s.charAt(index) - 'A'];
559	        if (index > 1 && mapped != '0') {
560	            char hw = s.charAt(index - 1);
561	            if (hw == 'H' || hw == 'W') {
562	                char pre = s.charAt(index - 2);
563	                if (SOUNDEX_MAP[pre - 'A'] == mapped || pre == 'H' || pre == 'W') {
564	                    return 0;
565	                }
566	            }
567	        }
568	        return mapped;
569	    }
570	
571	    /**
572	     * The lower-case SHA-256 hex digest of the given string's UTF-8 bytes, used to derive the
573	     * {@link #getIdentityKey() identity key}.
574	     *
575	     * @param input the string to digest
576	     * @return the 64-character lower-case hex SHA-256 digest
577	     */
578	    private static String sha256Hex(String input) {
579	        try {
580	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
581	            StringBuilder hex = new StringBuilder(digest.length * 2);
582	            for (byte b : digest) {
583	                hex.append(String.format("%02x", b));
584	            }
585	            return hex.toString();
586	        } catch (NoSuchAlgorithmException e) {
587	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
588	        }
589	    }
