632	     */
633	    public Pet getPet(String name, boolean ignoreNew) {
634	        name = name.toLowerCase();
635	        for (Pet pet : getPetsInternal()) {
636	            if (!ignoreNew || !pet.isNew()) {
637	                String compName = pet.getName();
638	                compName = compName.toLowerCase();
639	                if (compName.equals(name)) {
640	                    return pet;
