203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
206	        String idempotencyKey = currentIdempotencyKey();
207	        if (idempotencyKey != null) {
208	            Owner alreadyCreated = findOwnerByIdempotencyKey(idempotencyKey);
209	            if (alreadyCreated != null) {
210	                OwnerDto existingDto = toOwnerDto(alreadyCreated);
211	                existingDto.setBulkSignupWarning(isBulkSignupWarningActive());
212	                existingDto.setCapacityWarning(isCapacityWarningActive(alreadyCreated.getCity()));
213	                return new ResponseEntity<>(existingDto, HttpStatus.OK);
214	            }
215	        }
216	        validateRequiredOwnerFields(ownerFieldsDto);
217	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
218	        LocalDate suppliedOrDefaultDate =
219	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
220	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
221	        rejectDailyLimitExceeded(registrationDate);
222	        rejectCityAtCapacity(ownerFieldsDto.getCity());
223	        HttpHeaders headers = new HttpHeaders();
224	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
225	        validatePostcode(owner.getCity(), owner.getPostcode());
226	        applyAddress(owner);
227	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
228	        owner.setTelephone(normalizedTelephone);
229	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
230	        owner.setEmail(normalizeEmail(owner.getEmail()));
231	        rejectDuplicateIdentity(owner);
232	        applyPossibleDuplicate(owner, declaredHouseholdMember);
233	        owner.setRegistrationDate(registrationDate);
234	        owner.setCustomerCode(
235	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
236	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
237	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
238	        owner.setIdempotencyKey(idempotencyKey);
239	        applyMembershipLevelCeiling(owner);
240	        this.clinicService.saveOwner(owner);
241	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
242	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
243	            owner.getMembershipNumber());
244	        emitOwnerCreatedEvent(owner);
245	        OwnerDto ownerDto = toOwnerDto(owner);
246	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
247	        ownerDto.setCapacityWarning(isCapacityWarningActive(owner.getCity()));
248	        headers.setLocation(UriComponentsBuilder.newInstance()
249	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
250	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
251	    }
