253	    /**
254	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} logger, in
255	     * addition to the human-readable audit line. The event carries a monotonically increasing sequence
256	     * number, the owner id, the owner's current primary identifier (the customer code) and the derived
257	     * membership level, serialized as a compact JSON object.
258	     *
259	     * @param owner the just-saved owner
260	     */
261	    private void emitOwnerCreatedEvent(Owner owner) {
262	        OwnerCreatedEvent event = OwnerCreatedEvent.of(OWNER_CREATE_SEQUENCE.incrementAndGet(),
263	            owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel());
264	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
265	    }
