267	    /**
268	     * The idempotency key supplied on the current create request, read from its {@code Idempotency-Key}
269	     * header. A blank value is treated as absent.
270	     *
271	     * @return the trimmed {@code Idempotency-Key} header, or {@code null} when it is absent or blank
272	     */
273	    private String currentIdempotencyKey() {
274	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
275	            String header = attributes.getRequest().getHeader("Idempotency-Key");
276	            if (header != null && !header.isBlank()) {
277	                return header.trim();
278	            }
279	        }
280	        return null;
281	    }
