283	    /**
284	     * Finds the owner originally created under the given idempotency key, so a repeated create carrying
285	     * an already-seen key returns that owner instead of creating a duplicate. The lowest-id match is
286	     * returned when more than one owner somehow carries the key.
287	     *
288	     * @param idempotencyKey the create request's idempotency key
289	     * @return the owner first created under the key, or {@code null} when the key has not been seen
290	     */
291	    private Owner findOwnerByIdempotencyKey(String idempotencyKey) {
292	        return this.clinicService.findAllOwners().stream()
293	            .filter(existing -> idempotencyKey.equals(existing.getIdempotencyKey()))
294	            .min(java.util.Comparator.comparing(Owner::getId))
295	            .orElse(null);
296	    }
