392	    /**
393	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
394	     * offending field is collected so the caller learns exactly which values must be supplied.
395	     *
396	     * @param ownerFieldsDto the submitted owner payload
397	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
398	     *         telephone is missing or blank
399	     */
400	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
401	        List<String> missingFields = new ArrayList<>();
402	        if (isBlank(ownerFieldsDto.getFirstName())) {
403	            missingFields.add("firstName");
404	        }
405	        if (isBlank(ownerFieldsDto.getLastName())) {
406	            missingFields.add("lastName");
407	        }
408	        if (isBlank(ownerFieldsDto.getAddressLine1())
409	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
410	            missingFields.add("address");
411	        }
412	        if (isBlank(ownerFieldsDto.getCity())) {
413	            missingFields.add("city");
414	        }
415	        if (isBlank(ownerFieldsDto.getTelephone())) {
416	            missingFields.add("telephone");
417	        }
418	        if (!missingFields.isEmpty()) {
419	            throw new MissingOwnerFieldsException(missingFields);
420	        }
421	    }
422	
423	    private boolean isBlank(String value) {
424	        return value == null || value.isBlank();
425	    }
