441	    /**
442	     * Counts the existing owners who, before this create, already share the given first and last name.
443	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
444	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
445	     * case or spacing still count as the same name.
446	     *
447	     * @param firstName the first name of the owner being created
448	     * @param lastName the last name of the owner being created
449	     * @return the number of existing owners sharing both names (zero when none)
450	     */
451	    private int countNamesakes(String firstName, String lastName) {
452	        String first = normalizeHouseholdField(firstName);
453	        String last = normalizeHouseholdField(lastName);
454	        return (int) this.clinicService.findAllOwners().stream()
455	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
456	                && normalizeHouseholdField(existing.getLastName()).equals(last))
457	            .count();
458	    }
