460	    /**
461	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
462	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
463	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
464	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
465	     * more owners the create is rejected as a conflict.
466	     *
467	     * @param city the city of the owner being created
468	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
469	     */
470	    /**
471	     * Rejects an owner create once the maximum number of owners have already been registered on the
472	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
473	     * which is always a business day (a weekend effective date is rolled forward to the following
474	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
475	     * business day the create is rejected as too many requests. Because a weekend effective date is
476	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
477	     *
478	     * @param businessDay the adjusted business day the owner being created would be registered on
479	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
480	     */
481	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
482	        long ownersOnDay = this.clinicService.findAllOwners().stream()
483	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
484	            .count();
485	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
486	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
487	        }
488	    }
489	
490	    /**
491	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
492	     * forward, and a date that lands on a listed public holiday is likewise rolled forward, until the
493	     * result is a weekday that is not a public holiday; a weekday that is not a holiday is returned
494	     * unchanged. This applies whether the date was supplied on the request or defaulted to the
495	     * server's current date.
496	     *
497	     * @param date the effective registration date (supplied or defaulted)
498	     * @return the first non-holiday weekday on or after the supplied date
499	     */
500	    /**
501	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
502	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
503	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
504	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
505	     *
506	     * @return {@code true} when more than the threshold number of owners are already registered on
507	     *         today's business day, otherwise {@code false}
508	     */
509	    private boolean isBulkSignupWarningActive() {
510	        LocalDate today = toBusinessDay(LocalDate.now());
511	        long ownersToday = this.clinicService.findAllOwners().stream()
512	            .filter(existing -> today.equals(existing.getRegistrationDate()))
513	            .count();
514	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
515	    }
516	
517	    /**
518	     * Reports whether a response naming the given city should carry a capacity warning. The warning is
519	     * active once the city already holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and one fewer
520	     * than {@link #MAX_OWNERS_PER_CITY} owners (40-49), signalling that it is approaching the per-city
521	     * capacity limit. Owners are grouped into a city case-insensitively after surrounding whitespace is
522	     * trimmed and internal runs are collapsed, mirroring {@link #rejectCityAtCapacity}. The hard
523	     * rejection at {@link #MAX_OWNERS_PER_CITY} is unaffected.
524	     *
525	     * @param city the city to evaluate
526	     * @return {@code true} when the city holds between the warning threshold and the capacity limit
527	     *         (exclusive) owners, otherwise {@code false}
528	     */
529	    private boolean isCapacityWarningActive(String city) {
530	        String normalizedCity = normalizeHouseholdField(city);
531	        long ownersInCity = this.clinicService.findAllOwners().stream()
532	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
533	            .count();
534	        return ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD && ownersInCity < MAX_OWNERS_PER_CITY;
535	    }
536	
537	    private LocalDate toBusinessDay(LocalDate date) {
538	        LocalDate adjusted = switch (date.getDayOfWeek()) {
539	            case SATURDAY -> date.plusDays(2);
540	            case SUNDAY -> date.plusDays(1);
541	            default -> date;
542	        };
543	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
544	            adjusted = adjusted.plusDays(1);
545	        }
546	        return adjusted;
547	    }
548	
549	    private boolean isWeekend(LocalDate date) {
550	        return switch (date.getDayOfWeek()) {
551	            case SATURDAY, SUNDAY -> true;
552	            default -> false;
553	        };
554	    }
555	
556	    private void rejectCityAtCapacity(String city) {
557	        String normalizedCity = normalizeHouseholdField(city);
558	        long ownersInCity = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
560	            .count();
561	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
562	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
563	        }
564	    }
