566	    /**
567	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
568	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
569	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
570	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
571	     * to the same base code only when they share a region and produce the same telephone-and-last-name
572	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
573	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
574	     *
575	     * @param postcode the owner's postcode, used first to derive the region
576	     * @param city the owner's city, used to derive the region when the postcode maps to none
577	     * @param normalizedTelephone the owner's normalized (E.164) telephone
578	     * @param lastName the owner's last name
579	     * @return the formatted, de-duplicated customer code
580	     */
581	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
582	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
583	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
584	        String baseCode = region + "-" + hash8;
585	        return deduplicateCustomerCode(baseCode);
586	    }
587	
588	    /**
589	     * De-duplicates a computed customer code against every existing owner's customer code. When no
590	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
591	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
592	     *
593	     * @param baseCode the computed, formatted customer code before de-duplication
594	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
595	     */
596	    private String deduplicateCustomerCode(String baseCode) {
597	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
598	            .map(Owner::getCustomerCode)
599	            .filter(java.util.Objects::nonNull)
600	            .collect(java.util.stream.Collectors.toSet());
601	        if (!existingCodes.contains(baseCode)) {
602	            return baseCode;
603	        }
604	        int n = 2;
605	        while (existingCodes.contains(baseCode + "-" + n)) {
606	            n++;
607	        }
608	        return baseCode + "-" + n;
609	    }
610	
611	    /**
612	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
613	     * customerCode is the owner's customer code and YY is the last two digits of the fiscal year (the
614	     * fiscal year starts on 1 July) that the business-day-adjusted registrationDate falls in
615	     * (e.g. 'NSW-1A2B3C4D-M27').
616	     *
617	     * @param customerCode the owner's customer code
618	     * @param registrationDate the owner's business-day-adjusted registration date
619	     * @return the formatted membership number
620	     */
621	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
622	        String yy = String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
623	        return customerCode + "-M" + yy;
624	    }
625	
626	    /**
627	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
628	     * country calling code. Australia ('+61') uses 9 national digits and the North American
629	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
630	     * E.164 length (8 to 15 digits overall).
631	     */
632	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
633	        java.util.Map.of("61", 9, "1", 10);
634	
635	    /**
636	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
637	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
638	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
639	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
640	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
641	     * E.164 string is what gets stored and returned.
642	     *
643	     * @param telephone the raw telephone value from the request
644	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
645	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
646	     *         national number has the wrong length for its country code
647	     */
648	    private String normalizeTelephone(String telephone) {
649	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
650	        String e164;
651	        if (cleaned.startsWith("+")) {
652	            e164 = cleaned;
653	        } else {
654	            String national = cleaned;
655	            if (national.startsWith("0")) {
656	                national = national.substring(1);
657	            }
658	            e164 = "+61" + national;
659	        }
660	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
661	            throw new InvalidOwnerFieldsException(List.of("telephone"));
662	        }
663	        validateNationalNumberLength(e164);
664	        return e164;
665	    }
666	
667	    /**
668	     * Rejects an E.164 telephone whose national number does not have the exact length its country
669	     * calling code requires. The digits after the leading '+' are split into the longest matching
670	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
671	     * code is known and the national number's length differs from the required count the telephone is
672	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
673	     *
674	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
675	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
676	     */
677	    private void validateNationalNumberLength(String e164) {
678	        String digits = e164.substring(1);
679	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
680	            String countryCode = digits.substring(0, codeLength);
681	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
682	            if (requiredNationalLength != null) {
683	                int nationalLength = digits.length() - codeLength;
684	                if (nationalLength != requiredNationalLength) {
685	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
686	                }
687	                return;
688	            }
689	        }
690	    }
691	
692	    /**
693	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
694	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
695	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
696	     * stored and returned is the value lower-cased.
697	     *
698	     * @param email the raw email value from the request, or {@code null} when none was supplied
699	     * @return the lower-cased email, or {@code null} when no email was supplied
700	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
701	     *         its domain is on the disposable-domain blocklist
702	     */
703	    private String normalizeEmail(String email) {
704	        if (email == null || email.isBlank()) {
705	            return null;
706	        }
707	        if (!EMAIL_PATTERN.matcher(email).matches()) {
708	            throw new InvalidOwnerFieldsException(List.of("email"));
709	        }
710	        String normalized = email.toLowerCase(Locale.ROOT);
711	        String domain = normalized.substring(normalized.indexOf('@') + 1);
712	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
713	            throw new InvalidOwnerFieldsException(List.of("email"));
714	        }
715	        return normalized;
716	    }
717	
718	    /**
719	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
720	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
721	     * When present it must be exactly four digits and, when the owner's city maps to a known region
722	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
723	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
724	     * region accepts any four-digit postcode.
725	     *
726	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
727	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
728	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
729	     *         for the city's region
730	     */
731	    private void validatePostcode(String city, String postcode) {
732	        if (postcode == null || postcode.isBlank()) {
733	            return;
734	        }
735	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
736	            throw new InvalidOwnerFieldsException(List.of("postcode"));
737	        }
738	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
739	        if (range == null) {
740	            return;
741	        }
742	        int value = Integer.parseInt(postcode);
743	        if (value < range[0] || value > range[1]) {
744	            throw new InvalidOwnerFieldsException(List.of("postcode"));
745	        }
746	    }
747	
748	    /**
749	     * Resolves an owner's address from the supplied structured and flat fields, preferring the
750	     * structured form. Whichever address fields were supplied are normalized (see
751	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
752	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (an
753	     * absent or blank {@code addressLine2} is cleared) and the composed {@code address} is the
754	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
755	     * appended when the latter is present. When no {@code addressLine1} is supplied the flat
756	     * {@code address} is used unchanged for backward compatibility and the structured lines are
757	     * cleared. The composed {@code address} is what every later step reads.
758	     *
759	     * @param owner the owner being created, mapped from the request but not yet normalized
760	     */
761	    private void applyAddress(Owner owner) {
762	        String line1 = normalizeAddress(owner.getAddressLine1());
763	        String line2 = normalizeAddress(owner.getAddressLine2());
764	        String flat = normalizeAddress(owner.getAddress());
765	        if (!line1.isEmpty()) {
766	            owner.setAddressLine1(line1);
767	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
768	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
769	        } else {
770	            owner.setAddressLine1(null);
771	            owner.setAddressLine2(null);
772	            owner.setAddress(flat);
773	        }
774	    }
775	
776	    /**
777	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
778	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
779	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
780	     * normalized form is what gets stored, returned and used for every address comparison (the
781	     * required-field check, household duplicate detection and the shared household id).
782	     *
783	     * @param address the raw address value from the request, or {@code null}
784	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
785	     */
786	    private String normalizeAddress(String address) {
787	        if (address == null) {
788	            return "";
789	        }
790	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
791	        if (collapsed.isEmpty()) {
792	            return "";
793	        }
794	        String[] tokens = collapsed.split(" ");
795	        for (int i = 0; i < tokens.length; i++) {
796	            switch (tokens[i]) {
797	                case "ST" -> tokens[i] = "STREET";
798	                case "RD" -> tokens[i] = "ROAD";
799	                case "AVE" -> tokens[i] = "AVENUE";
800	                default -> { }
801	            }
802	        }
803	        return String.join(" ", tokens);
804	    }
805	
806	    /**
807	     * Rejects an owner create whose {@code identityKey} exactly matches a non-deleted existing owner's.
808	     * The identity key - the SHA-256 hex digest over the owner's normalized telephone, lower-cased email
809	     * (empty when none) and the Soundex code of its last name, joined by {@code '|'} - is the single
810	     * derived value used for duplicate detection; owners flagged deleted are ignored. Only a whole-key
811	     * match is a conflict, so two owners with the same last name and postcode but different telephones
812	     * have different keys and are both allowed; only an owner whose entire key is identical is a
813	     * duplicate.
814	     *
815	     * @param owner the owner being created, with its telephone, email and last name already resolved
816	     * @throws DuplicateOwnerIdentityException if another non-deleted owner already has this exact identity key
817	     */
818	    private void rejectDuplicateIdentity(Owner owner) {
819	        String identityKey = owner.getIdentityKey();
820	        boolean inUse = this.clinicService.findAllOwners().stream()
821	            .filter(existing -> !existing.isDeleted())
822	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
823	        if (inUse) {
824	            throw new DuplicateOwnerIdentityException(identityKey);
825	        }
826	    }
827	
828	    /**
829	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
830	     * whose last name shares this owner's Soundex code and whose postcode matches, yet whose
831	     * {@code identityKey} differs; such an owner is not a hard duplicate (its whole identity key
832	     * differs) and is still created. When at least one soft match exists, {@code possibleDuplicate} is
833	     * set true and {@code possibleDuplicateOf} to the lowest-id match; otherwise {@code possibleDuplicate}
834	     * is false and {@code possibleDuplicateOf} is left unset.
835	     * <p>
836	     * A declared household member - an owner that acknowledged sharing an existing household via
837	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
838	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
839	     *
840	     * @param owner the owner being created, with its last name, postcode, email and normalized
841	     *        telephone resolved
842	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
843	     */
844	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
845	        if (declaredHouseholdMember) {
846	            owner.setPossibleDuplicate(false);
847	            return;
848	        }
849	        String soundex = Owner.soundex(owner.getLastName());
850	        String postcode = owner.getPostcode();
851	        String identityKey = owner.getIdentityKey();
852	        Owner match = null;
853	        if (postcode != null && !postcode.isBlank()) {
854	            match = this.clinicService.findAllOwners().stream()
855	                .filter(existing -> !existing.isDeleted())
856	                .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex))
857	                .filter(existing -> postcode.equals(existing.getPostcode()))
858	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
859	                .min(java.util.Comparator.comparing(Owner::getId))
860	                .orElse(null);
861	        }
862	        if (match != null) {
863	            owner.setPossibleDuplicate(true);
864	            owner.setPossibleDuplicateOf(match.getId());
865	        } else {
866	            owner.setPossibleDuplicate(false);
867	        }
868	    }
869	
870	    /**
871	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
872	     * household member count} for the response.
873	     *
874	     * @param owner the owner to map
875	     * @return the mapped owner DTO
876	     */
877	    private OwnerDto toOwnerDto(Owner owner) {
878	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
879	        return ownerMapper.toOwnerDto(owner);
880	    }
881	
882	    /**
883	     * Counts the members of the given owner's household - the owners that share this owner's
884	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
885	     * is {@code null}) is its own sole member, so the count is one.
886	     *
887	     * @param owner the owner whose household is being sized
888	     * @return the number of owners sharing this owner's household (one when it has no household)
889	     */
890	    private int countHouseholdMembers(Owner owner) {
891	        String householdId = owner.getHouseholdId();
892	        if (householdId == null) {
893	            return 1;
894	        }
895	        return (int) this.clinicService.findAllOwners().stream()
896	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
897	            .count();
898	    }
899	
900	    /**
901	     * Caps the membership level of an owner being created so it can never exceed one above the current
902	     * maximum membership level among the other members of its household. The ceiling stored is that
903	     * maximum plus one; the owner's derived {@link Owner#getMembershipLevel() membership level} is then
904	     * never reported above it. An owner that joined no existing household - it has no {@code householdId}
905	     * or is the sole member of its household - is left uncapped so no ceiling applies.
906	     *
907	     * @param owner the owner being created, with its {@code householdId} already resolved
908	     */
909	    private void applyMembershipLevelCeiling(Owner owner) {
910	        String householdId = owner.getHouseholdId();
911	        if (householdId == null) {
912	            return;
913	        }
914	        OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
915	            .filter(existing -> !existing.isDeleted())
916	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
917	            .mapToInt(this::currentMembershipLevel)
918	            .max();
919	        if (maxLevel.isPresent()) {
920	            owner.setMembershipLevelCeiling(maxLevel.getAsInt() + 1);
921	        }
922	    }
923	
924	    /**
925	     * The membership level an existing owner currently reports, computed the same way as for a response
926	     * by first populating its {@link Owner#getHouseholdMemberCount() household member count}.
927	     *
928	     * @param member the existing household member whose membership level is needed
929	     * @return the member's current membership level
930	     */
931	    private int currentMembershipLevel(Owner member) {
932	        member.setHouseholdMemberCount(countHouseholdMembers(member));
933	        return member.getMembershipLevel();
934	    }
935	
936	    /**
937	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
938	     * last name and a postcode: the {@code householdId} is derived deterministically from the
939	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
940	     * owners with the same last name and postcode always resolve to the same identifier and belong to
941	     * the same household automatically - no acknowledgement is needed to create the link.
942	     * <p>
943	     * When the owner supplies a postcode its {@code householdId} is always assigned; an owner with no
944	     * postcode belongs to no household and is left without an identifier. Joining an existing household
945	     * is not itself a conflict: hard duplicate detection is handled solely by the identity key (see
946	     * {@link #rejectDuplicateIdentity(Owner)}), so two members of one household with different
947	     * telephones are both created. An owner that explicitly acknowledges an existing household via
948	     * {@code sharesHousehold} is reported as a declared member so it is not flagged as a possible
949	     * duplicate.
950	     *
951	     * @param owner the owner being created
952	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
953	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
954	     *         {@code false}
955	     */
956	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
957	        String postcode = owner.getPostcode();
958	        if (postcode == null || postcode.isBlank()) {
959	            return false;
960	        }
961	        String lastName = normalizeHouseholdField(owner.getLastName());
962	        String householdId = generateHouseholdId(lastName, postcode);
963	        owner.setHouseholdId(householdId);
964	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
965	            .filter(existing -> !existing.isDeleted())
966	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
967	        return hasExistingMember && Boolean.TRUE.equals(sharesHousehold);
968	    }
969	
970	    /**
971	     * Builds the stable identifier shared by the members of one household. It is derived purely from
972	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
973	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
974	     * two fields joined by a single '|'.
975	     *
976	     * @param normalizedLastName the household's last name, already normalized for comparison
977	     * @param postcode the household's postcode
978	     * @return the shared household identifier
979	     */
980	    private String generateHouseholdId(String normalizedLastName, String postcode) {
981	        String key = normalizedLastName + '|' + postcode;
982	        try {
983	            byte[] digest = MessageDigest.getInstance("SHA-256")
984	                .digest(key.getBytes(StandardCharsets.UTF_8));
985	            StringBuilder hex = new StringBuilder();
986	            for (byte b : digest) {
987	                hex.append(String.format("%02X", b));
988	                if (hex.length() >= 12) {
989	                    break;
990	                }
991	            }
992	            return hex.substring(0, 12);
993	        } catch (NoSuchAlgorithmException e) {
994	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
995	        }
996	    }
997	
998	    /**
999	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
1000	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
1001	     * the owner's normalized telephone and last name.
1002	     *
1003	     * @param input the string to digest
1004	     * @param length the number of leading upper-case hex characters to return
1005	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
1006	     */
1007	    private String sha256UpperHex(String input, int length) {
1008	        try {
1009	            byte[] digest = MessageDigest.getInstance("SHA-256")
1010	                .digest(input.getBytes(StandardCharsets.UTF_8));
1011	            StringBuilder hex = new StringBuilder();
1012	            for (byte b : digest) {
1013	                hex.append(String.format("%02X", b));
1014	                if (hex.length() >= length) {
1015	                    break;
1016	                }
1017	            }
1018	            return hex.substring(0, length);
1019	        } catch (NoSuchAlgorithmException e) {
1020	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1021	        }
1022	    }
1023	
1024	    /**
1025	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
1026	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
1027	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
1028	     * expands common abbreviations.
1029	     *
1030	     * @param value the raw last name, or {@code null}
1031	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
1032	     */
1033	    private String normalizeHouseholdField(String value) {
1034	        if (value == null) {
1035	            return "";
1036	        }
1037	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1038	    }
1039	}
