        if (letters.length() == 0) {
            return "";
        }
        String s = letters.toString();
        char[] out = {'0', '0', '0', '0'};
        out[0] = s.charAt(0);
        char last = soundexCode(s, 0);
        int count = 1;
        for (int i = 1; i < s.length() && count < out.length; i++) {
            char mapped = soundexCode(s, i);
            if (mapped != 0) {
                if (mapped != '0' && mapped != last) {
