     */
    private static char soundexCode(String s, int index) {
        char mapped = SOUNDEX_MAP[s.charAt(index) - 'A'];
        if (index > 1 && mapped != '0') {
            char hw = s.charAt(index - 1);
            if (hw == 'H' || hw == 'W') {
                char pre = s.charAt(index - 2);
